const CACHE='tie-breaker-v10';
const assets=['./','./index.html','./style.css','./game.js','./match.js','./joystick.js','./animation.js','./venue.js','./three.module.js','./three.core.js','./manifest.webmanifest','./icon-192.png','./icon-512.png',...['venue-hard.jpg','venue-clay.jpg','venue-grass.jpg','venue-indoor.jpg','player.png','cpu.png','hard.jpg','indoor.jpg','clay.jpg','grass.jpg','player_forehand.png','player_lob.png','player_serve.png','cpu_forehand.png','cpu_lob.png','cpu_serve.png','player_run_left.png','player_run_right.png','cpu_run_left.png','cpu_run_right.png','player_run_forward.png','player_run_backward.png','cpu_run_forward.png','cpu_run_backward.png','player_hold.png','player_toss.png','cpu_hold.png','cpu_toss.png'].map(n=>'./assets/'+n)];
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(c=>c.addAll(assets)))});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===location.origin)e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(v=>{if(v.ok){const cp=v.clone();caches.open(CACHE).then(c=>c.put(e.request,cp));}return v})))})
